/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
changed = {
    'local/bin/review.sh': [(250, 720)],
    'local/protocols/review.md': [(1, 130), (238, 260), (380, 420)],
    'local/protocols/EVOLUTION.md': [(1870, 1930)],
    'scripts/tests/test_github_workflow.py': [(180, 220), (600, 900)],
    'results/telemetry/events.md': [(10108, 10130)],
}
for name, ranges in changed.items():
    lines = Path(name).read_text(encoding='utf-8').splitlines()
    bad = []
    for start, end in ranges:
        for number in range(start, min(end, len(lines)) + 1):
            if len(lines[number - 1]) > 100:
                bad.append((number, len(lines[number - 1]), lines[number - 1]))
    print(f'{name}: {len(bad)} overlong lines in changed ranges')
    for number, size, line in bad:
        print(f'  {number}:{size} {line}')
PY"

